import React, { useState, useEffect, useRef } from "react";
import Chart from 'chart.js/auto';

// Los datos iniciales y las constantes (initialExpenses, defaultCategories, etc.) no cambian.
// ... (Puedes mantener la parte inicial de tu archivo igual)

const initialExpenses = [
  {
    id: 1,
    date: "2023-08-10",
    category: "arriendo",
    amount: 1200000,
    paymentMethod: "transferencia",
    description: "Arriendo oficina central",
    receipt: null,
  },
  {
    id: 2,
    date: "2023-08-05",
    category: "servicios",
    amount: 150000,
    paymentMethod: "tarjeta",
    description: "Pago de servicios básicos",
    receipt: null,
  },
];

const defaultCategories = [
  "arriendo",
  "servicios",
  "insumos",
  "sueldos",
  "imprevistos",
];
const defaultPaymentMethods = ["efectivo", "transferencia", "tarjeta"];


function ExpensesPage() {
  // --- ESTADOS (SIN CAMBIOS) ---
  const [expenses, setExpenses] = useState(() => {
    const stored = localStorage.getItem("expenses");
    return stored ? JSON.parse(stored) : initialExpenses;
  });
  const [categories, setCategories] = useState(() => {
    const stored = localStorage.getItem("expenseCategories");
    return stored ? JSON.parse(stored) : defaultCategories;
  });
  const [form, setForm] = useState({
    date: "",
    category: "",
    amount: "",
    paymentMethod: "",
    description: "",
    receipt: null,
  });
  const [filters, setFilters] = useState({
    dateRange: "",
    category: "",
    paymentMethod: "",
    search: "",
  });
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;
  const [showCategoryModal, setShowCategoryModal] = useState(false);
  const [newCategory, setNewCategory] = useState("");
  const [showEditModal, setShowEditModal] = useState(false);
  const [editExpense, setEditExpense] = useState(null);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [deleteExpenseId, setDeleteExpenseId] = useState(null);
  const monthlyChartRef = useRef(null);
  const monthlyChartInstance = useRef(null);
  const categoryChartRef = useRef(null);
  const categoryChartInstance = useRef(null);
  const [budgetLimit] = useState(5000000);
  const [showBudgetAlert, setShowBudgetAlert] = useState(false);

  // --- NUEVO ESTADO PARA VISIBILIDAD DEL FORMULARIO ---
  const [showAddForm, setShowAddForm] = useState(false);


  // --- LÓGICA DE useEffect y Handlers (SIN CAMBIOS) ---
  // ... (Toda la lógica de useEffect, handleSubmit, handleChange, etc. se mantiene igual)
  useEffect(() => {
    // --- Gráfico mensual ---
    if (monthlyChartInstance.current) {
      monthlyChartInstance.current.destroy();
    }
    const now = new Date();
    const months = [];
    const monthLabels = [];
    for (let i = 5; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      months.push(key);
      monthLabels.push(d.toLocaleString('es-CL', { month: 'short', year: 'numeric' }));
    }
    const monthlyTotals = months.map((key) =>
      expenses.filter(e => e.date && e.date.startsWith(key)).reduce((sum, e) => sum + Number(e.amount), 0)
    );
    if (monthlyChartRef.current) {
      monthlyChartInstance.current = new Chart(monthlyChartRef.current, {
        type: 'bar',
        data: {
          labels: monthLabels,
          datasets: [{
            label: 'Gastos',
            data: monthlyTotals,
            backgroundColor: '#3b82f6', // Un azul más estándar
          }],
        },
        options: {
          plugins: { legend: { display: false } },
          responsive: true,
        },
      });
    }

    // --- Gráfico por categoría ---
    if (categoryChartInstance.current) {
      categoryChartInstance.current.destroy();
    }
    const catTotals = {};
    expenses.forEach(e => {
      if (!catTotals[e.category]) catTotals[e.category] = 0;
      catTotals[e.category] += Number(e.amount);
    });
    const catLabels = Object.keys(catTotals).map(c => c.charAt(0).toUpperCase() + c.slice(1));
    const catData = Object.values(catTotals);
    const catColors = catLabels.map((_, i) => `hsl(${i * 50},70%,60%)`);
    if (categoryChartRef.current) {
      categoryChartInstance.current = new Chart(categoryChartRef.current, {
        type: 'doughnut',
        data: {
          labels: catLabels,
          datasets: [{
            data: catData,
            backgroundColor: catColors,
          }],
        },
        options: {
          plugins: { legend: { position: 'bottom' } },
          responsive: true,
        },
      });
    }

    // --- Alerta de presupuesto ---
    const thisMonth = now.toISOString().slice(0,7);
    const totalMonth = expenses.filter(e => e.date && e.date.startsWith(thisMonth)).reduce((sum, e) => sum + Number(e.amount), 0);
    setShowBudgetAlert(totalMonth > budgetLimit);

  }, [expenses, budgetLimit]);

  const filteredExpenses = expenses.filter((e) => {
    if (filters.category && e.category !== filters.category) return false;
    if (filters.paymentMethod && e.paymentMethod !== filters.paymentMethod) return false;
    if (filters.search && !(
      e.description?.toLowerCase().includes(filters.search.toLowerCase()) ||
      e.category?.toLowerCase().includes(filters.search.toLowerCase())
    )) return false;
    if (filters.dateRange) {
      const [from, to] = filters.dateRange.split(" to ");
      if (from && e.date < from) return false;
      if (to && e.date > to) return false;
    }
    return true;
  });

  const totalPages = Math.ceil(filteredExpenses.length / itemsPerPage);
  const paginatedExpenses = filteredExpenses.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "receipt") {
      setForm({ ...form, receipt: files[0] });
    } else {
      setForm({ ...form, [name]: value });
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setExpenses([
      ...expenses,
      {
        ...form,
        id: expenses.length ? Math.max(...expenses.map((e) => e.id)) + 1 : 1,
      },
    ]);
    setForm({
      date: "",
      category: "",
      amount: "",
      paymentMethod: "",
      description: "",
      receipt: null,
    });
    setShowAddForm(false); // Ocultar el formulario después de enviar
    setCurrentPage(1);
  };

  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters((f) => ({ ...f, [name]: value }));
    setCurrentPage(1);
  };

  const handleAddCategory = (e) => {
    e.preventDefault();
    if (newCategory && !categories.includes(newCategory.toLowerCase())) {
      setCategories([...categories, newCategory.toLowerCase()]);
    }
    setNewCategory("");
    setShowCategoryModal(false);
  };

  const openEditModal = (expense) => {
    setEditExpense(expense);
    setShowEditModal(true);
  };
  const handleEditChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "receipt") {
      setEditExpense({ ...editExpense, receipt: files[0] });
    } else {
      setEditExpense({ ...editExpense, [name]: value });
    }
  };
  const handleEditSubmit = (e) => {
    e.preventDefault();
    setExpenses((prev) =>
      prev.map((g) => (g.id === editExpense.id ? editExpense : g))
    );
    setShowEditModal(false);
  };

  const openDeleteModal = (id) => {
    setDeleteExpenseId(id);
    setShowDeleteModal(true);
  };
  const handleDelete = () => {
    setExpenses((prev) => prev.filter((g) => g.id !== deleteExpenseId));
    setShowDeleteModal(false);
  };


  // --- RENDER (DISEÑO MODIFICADO) ---
  return (
    <div className="bg-gray-50 min-h-screen">
      <div className="container mx-auto px-4 py-8">
        <h1 className="text-4xl font-bold text-gray-800 mb-8 text-center">
          Control de Gastos
        </h1>

        {/* Alerta de presupuesto */}
        {showBudgetAlert && (
          <div className="mb-6 bg-red-100 border-l-4 border-red-500 text-red-700 p-4 text-lg">
            <strong>¡Atención!</strong> Has superado el límite de presupuesto mensual.
          </div>
        )}

        {/* Gráficos */}
        <section className="mb-8">
            <h2 className="text-2xl font-bold text-gray-700 mb-4">Resumen Visual</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="bg-white p-6 rounded-lg shadow-md">
                    <h3 className="text-xl font-semibold mb-2">Gastos Mensuales</h3>
                    <canvas ref={monthlyChartRef}></canvas>
                </div>
                <div className="bg-white p-6 rounded-lg shadow-md">
                    <h3 className="text-xl font-semibold mb-2">Gastos por Categoría</h3>
                    <canvas ref={categoryChartRef}></canvas>
                </div>
            </div>
        </section>

        {/* Botón principal para agregar gasto */}
        <div className="text-center mb-8">
          <button
            onClick={() => setShowAddForm(!showAddForm)}
            className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-lg text-xl shadow-lg"
          >
            {showAddForm ? 'Ocultar Formulario' : 'Agregar Nuevo Gasto'}
          </button>
        </div>

        {/* Formulario de registro (condicional) */}
        {showAddForm && (
          <section className="bg-white rounded-lg shadow-lg p-8 mb-8">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-gray-800">Registrar un Gasto</h2>
              <button
                className="text-blue-600 hover:underline font-semibold"
                onClick={() => setShowCategoryModal(true)}
                type="button"
              >
                + Nueva Categoría
              </button>
            </div>
            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Clases aumentadas para inputs: text-lg, p-3 */}
              <input type="date" name="date" value={form.date} onChange={handleChange} className="w-full border-gray-300 border rounded-md px-4 py-3 text-lg" required />
              <select name="category" value={form.category} onChange={handleChange} className="w-full border-gray-300 border rounded-md px-4 py-3 text-lg" required>
                <option value="">Seleccione Categoría</option>
                {categories.map((cat) => <option key={cat} value={cat}>{cat.charAt(0).toUpperCase() + cat.slice(1)}</option>)}
              </select>
              <input type="number" name="amount" value={form.amount} onChange={handleChange} className="w-full border-gray-300 border rounded-md px-4 py-3 text-lg" placeholder="Monto (ej: 50000)" required />
              <select name="paymentMethod" value={form.paymentMethod} onChange={handleChange} className="w-full border-gray-300 border rounded-md px-4 py-3 text-lg" required>
                <option value="">Seleccione Método de pago</option>
                {defaultPaymentMethods.map((m) => <option key={m} value={m}>{m.charAt(0).toUpperCase() + m.slice(1)}</option>)}
              </select>
              <input type="text" name="description" value={form.description} onChange={handleChange} className="w-full border-gray-300 border rounded-md px-4 py-3 text-lg" placeholder="Descripción (opcional)" />
              <div>
                  <label className="block text-md font-medium text-gray-700 mb-1">Comprobante (opcional)</label>
                  <input type="file" name="receipt" onChange={handleChange} className="w-full text-gray-700" accept="image/*,.pdf" />
              </div>
              <button type="submit" className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-4 rounded-lg text-lg">
                Guardar Gasto
              </button>
            </form>
          </section>
        )}

        {/* Filtros y listado de gastos */}
        <section className="bg-white rounded-lg shadow-lg p-8">
          <h2 className="text-2xl font-bold text-gray-800 mb-6">Historial de Gastos</h2>
          {/* Filtros */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
              {/* Inputs de filtros con texto más grande */}
              <input type="text" name="search" value={filters.search} onChange={handleFilterChange} className="w-full rounded-md border-gray-300 shadow-sm px-4 py-2 border text-base" placeholder="Buscar..."/>
              <select name="category" value={filters.category} onChange={handleFilterChange} className="w-full rounded-md border-gray-300 shadow-sm px-4 py-2 border text-base">
                  <option value="">Todas las categorías</option>
                  {categories.map((cat) => <option key={cat} value={cat}>{cat.charAt(0).toUpperCase() + cat.slice(1)}</option>)}
              </select>
              {/* ... otros filtros */}
          </div>
          
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-300">
              <thead className="bg-gray-100">
                <tr>
                  {/* Headers con texto más grande y en negrita */}
                  <th className="px-6 py-3 text-left text-lg font-bold text-gray-600">Fecha</th>
                  <th className="px-6 py-3 text-left text-lg font-bold text-gray-600">Categoría</th>
                  <th className="px-6 py-3 text-left text-lg font-bold text-gray-600">Monto</th>
                  <th className="px-6 py-3 text-left text-lg font-bold text-gray-600">Descripción</th>
                  <th className="px-6 py-3 text-left text-lg font-bold text-gray-600">Acciones</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {paginatedExpenses.map((g) => (
                  <tr key={g.id} className="hover:bg-gray-50">
                    {/* Celdas con texto más grande */}
                    <td className="px-6 py-4 text-lg text-gray-800">{g.date}</td>
                    <td className="px-6 py-4 text-lg text-gray-800 capitalize">{g.category}</td>
                    <td className="px-6 py-4 text-lg text-gray-800">${Number(g.amount).toLocaleString()}</td>
                    <td className="px-6 py-4 text-lg text-gray-800">{g.description}</td>
                    <td className="px-6 py-4">
                      {/* Botones de acción más claros */}
                      <button className="bg-yellow-500 text-white font-semibold py-1 px-3 rounded mr-2" onClick={() => openEditModal(g)}>
                        Editar
                      </button>
                      <button className="bg-red-600 text-white font-semibold py-1 px-3 rounded" onClick={() => openDeleteModal(g.id)}>
                        Eliminar
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {/* Paginación (sin cambios mayores) */}
        </section>

        {/* Los Modales (Editar, Eliminar, Agregar Categoría) no necesitan grandes cambios estructurales,
            pero se beneficiarían de aumentar el tamaño del texto y los botones internos.
            El código para los modales se mantiene igual. */}

        {showCategoryModal && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl p-6 max-w-md w-full">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold text-gray-800">Agregar Nueva Categoría</h3>
              <button className="text-gray-500 hover:text-gray-700" onClick={() => setShowCategoryModal(false)}>
                X
              </button>
            </div>
            <form onSubmit={handleAddCategory}>
              <input
                type="text"
                value={newCategory}
                onChange={(e) => setNewCategory(e.target.value)}
                className="w-full border rounded px-3 py-2 mb-4"
                placeholder="Nombre de la categoría"
                required
              />
              <div className="flex justify-end space-x-2">
                <button type="button" className="px-4 py-2 bg-gray-200 rounded" onClick={() => setShowCategoryModal(false)}>
                  Cancelar
                </button>
                <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded">
                  Agregar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showEditModal && editExpense && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl p-6 max-w-lg w-full">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold text-gray-800">Editar Gasto</h3>
              <button className="text-gray-500 hover:text-gray-700" onClick={() => setShowEditModal(false)}>
                X
              </button>
            </div>
            <form onSubmit={handleEditSubmit} className="space-y-4">
              <input type="date" name="date" value={editExpense.date} onChange={handleEditChange} className="w-full border rounded px-3 py-2" required />
              <select name="category" value={editExpense.category} onChange={handleEditChange} className="w-full border rounded px-3 py-2" required >
                <option value="">Categoría</option>
                {categories.map((cat) => <option key={cat} value={cat}>{cat.charAt(0).toUpperCase() + cat.slice(1)}</option>)}
              </select>
              <input type="number" name="amount" value={editExpense.amount} onChange={handleEditChange} className="w-full border rounded px-3 py-2" placeholder="Monto" required />
              <select name="paymentMethod" value={editExpense.paymentMethod} onChange={handleEditChange} className="w-full border rounded px-3 py-2" required>
                <option value="">Método de pago</option>
                {defaultPaymentMethods.map((m) => <option key={m} value={m}>{m.charAt(0).toUpperCase() + m.slice(1)}</option>)}
              </select>
              <input type="text" name="description" value={editExpense.description} onChange={handleEditChange} className="w-full border rounded px-3 py-2" placeholder="Descripción" />
              <input type="file" name="receipt" onChange={handleEditChange} className="w-full border rounded px-3 py-2" accept="image/*,.pdf" />
              <div className="flex justify-end space-x-2">
                <button type="button" className="px-4 py-2 bg-gray-200 rounded" onClick={() => setShowEditModal(false)}>
                  Cancelar
                </button>
                <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded">
                  Guardar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showDeleteModal && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl p-6 max-w-md w-full">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold text-gray-800">Confirmar Eliminación</h3>
              <button className="text-gray-500 hover:text-gray-700" onClick={() => setShowDeleteModal(false)}>
                X
              </button>
            </div>
            <p className="text-gray-600 mb-6">¿Estás seguro de que deseas eliminar este gasto? Esta acción no se puede deshacer.</p>
            <div className="flex justify-end space-x-2">
              <button className="px-4 py-2 bg-gray-200 rounded text-gray-700" onClick={() => setShowDeleteModal(false)}>
                Cancelar
              </button>
              <button className="px-4 py-2 bg-red-600 text-white rounded" onClick={handleDelete}>
                Eliminar
              </button>
            </div>
          </div>
        </div>
      )}
      </div>
    </div>
  );
}

export default ExpensesPage;
